(() => {
  const name = 'rth_cookie_notice';
  const notice = document.querySelector('.cookiealert');

  if (!notice || document.cookie.split('; ').some((item) => item.startsWith(`${name}=accepted`))) {
    return;
  }

  notice.hidden = false;
  notice.querySelector('.acceptcookies')?.addEventListener('click', () => {
    const secure = window.location.protocol === 'https:' ? '; Secure' : '';
    document.cookie = `${name}=accepted; Max-Age=31536000; Path=/; SameSite=Lax${secure}`;
    notice.hidden = true;
  });
})();
